select
    *
from
    tb_building

        deleted = 0
    and id = #{id}
    and school_id = #{schoolId}
    and school_name = #{schoolName}
    and compus_id = #{compusId}
    and compus_name = #{compusName}
    and build_category_id = #{buildCategoryId}
    and number_id = #{numberId}
    and building_name = #{buildingName}
